import {VEHICLES,WHEELS,INTERIORS,CITIES,LANGS,ROUTES,LOCALES,PHOTO_CREDITS,INTRO_CLIP,INTRO_MUSIC,TESLA_FILMS} from './data.mjs?v=10';
import {translator} from './i18n.mjs?v=10';
import {vehicle,defaultConfig,configuration,money,number,recommend,encodeConfig,decodeConfig,initialConfig,rememberConfig,readComparison,rememberComparison,loadState,validateGarage,planEnergy,haversine,fetchRoute,fetchWeather,routePath} from './core.mjs?v=7';
import {createExperience} from './experience.mjs?v=7';
import {createRouteMap} from './route-map.mjs?v=7';
const root=document.getElementById('app');
const routeMap=createRouteMap({doc:document,win:window});
const experience=createExperience({root,win:window,doc:document});
let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error('unavailable')},setItem(){throw Error('unavailable')}};}
let state=loadState(storage), t=translator(state.lang), menuOpen=false, compare=readComparison(storage),filter='all',sort='design',cfg=photoConfiguration(initialConfig(storage,location.search));
let configRemembered=true,clockTimer;
const AUTHOR='Natalie (Netaniya) Ragulina';
function authorStrip(cls='project-meta'){return `<div class="${cls}"><p>${t('developedBy')} <strong>${AUTHOR}</strong></p><time data-munich-clock aria-live="off"></time></div>`;}
function updateClock(){clearTimeout(clockTimer);const now=new Date();const text=t('munich')+' | '+new Intl.DateTimeFormat(LOCALES[state.lang],{timeZone:'Europe/Berlin',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(now);for(const el of document.querySelectorAll('[data-munich-clock]')){el.textContent=text;el.setAttribute('datetime',now.toISOString());}clockTimer=setTimeout(updateClock,1000);}
window.addEventListener('pageshow',updateClock);window.addEventListener('pagehide',()=>clearTimeout(clockTimer));
let quiz={budget:90000,seats:5,priority:'distance'},quizResult=null,trip={from:'munich',to:'salzburg',model:'gt-01',start:90,reserve:15,price:.59},tripResult=null,tripBusy=false,tripFailed=false,weatherResult=null,weatherBusy=false,weatherFailed=false,controller=null,weatherController=null,toastTimer;
const path=location.pathname.endsWith('/')?location.pathname:location.pathname+'/';
const isHome=path==='/', isKnown=ROUTES.includes(path);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<span aria-hidden="true">↗</span>';
const a=(href,label,cls='')=>`<a class="${cls}" href="${esc(href)}">${esc(label)} ${arrow}</a>`;
const num=(n,d=0)=>number(n,state.lang,d),curr=c=>money(c,state.lang);
function img(v,cls=''){return `<img class="car-image vehicle-photo ${cls}" src="/assets/${v.image}" alt="${esc(v.name+' · '+t('photoLabel'))}" width="${v.imageWidth||1600}" height="${v.imageHeight||1000}" ${cls==='hero-car'?'fetchpriority="high"':'loading="lazy"'}>`;}
function heading(text,tag='h2',attrs=''){return `<${tag} class="balanced-heading" ${attrs}>${String(text).split(/\s*[—–]\s*/u).map(line=>`<span class="heading-line">${esc(line.trim())}</span>`).join('\n')}</${tag}>`;}

function header(){const nav=[['/collection/','navCollection'],['/finder/','navFinder'],['/configure/','navConfig'],['/journey/','navJourney'],['/garage/','navGarage']];return `<a class="skip-link" href="#main">${t('skip')}</a><header class="site-header">${authorStrip()}<div class="header-inner"><button class="menu-toggle" type="button" data-action="menu" aria-expanded="${menuOpen}" aria-controls="main-nav" aria-label="${t(menuOpen?'close':'menu')}"><span></span><span></span></button><a href="/" class="wordmark" aria-label="Motion Atelier · ${esc(t('backHome'))}">MOTION ATELIER</a><button class="theme-toggle" type="button" data-action="theme" aria-label="${t(state.theme==='dark'?'themeLight':'themeDark')}" title="${t(state.theme==='dark'?'themeLight':'themeDark')}"><span aria-hidden="true">${state.theme==='dark'?'☀︎':'☾'}</span></button><label class="language"><span class="language-code" aria-hidden="true">${state.lang==='uk'?'UA':state.lang.toUpperCase()}<span>⌄</span></span><span class="sr-only">${t('language')}</span><select id="language" aria-label="${t('language')}">${[['de','DE · Deutsch'],['en','EN · English'],['ru','RU · Русский'],['uk','UA · Українська']].map(([k,v])=>`<option value="${k}" ${state.lang===k?'selected':''}>${v}</option>`).join('')}</select></label></div><nav id="main-nav" class="main-nav ${menuOpen?'open':''}" aria-label="${t('menu')}">${nav.map(([href,key])=>`<a href="${href}" ${path===href?'aria-current="page"':''}>${t(key)}${key==='navGarage'&&state.garage.length?` <span class="count">${state.garage.length}</span>`:''}</a>`).join('')}</nav></header>`;}
function footer(){return `<footer class="site-footer"><div class="footer-top"><a class="wordmark" href="/">MOTION ATELIER</a><p>${t('heroSub')}</p></div><div class="footer-bottom"><span>${t('demo')}</span><div>${a('/about/',t('navAbout'))}<a href="https://github.com/Netaniya/Netaniya/tree/main/portfolio/motion-atelier" target="_blank" rel="noopener noreferrer">GitHub ↗</a></div><span>© 2026 Natalie Ragulina (Netaniya)</span></div></footer>`;}
function specs(v){return `<dl class="specs"><div><dt>${t('range')}</dt><dd>${num(Math.floor(v.battery/v.consumption*100))}<small>${t('unitKm')}</small></dd></div><div><dt>${t('power')}</dt><dd>${num(v.power)}<small>${t('unitKw')}</small></dd></div><div><dt>${t('seats')}</dt><dd>${v.seats}</dd></div></dl>`;}
function vehicleCard(v,{selection=false,saved=null}={}){return `<article class="vehicle-card ${compare.has(v.id)?'selected':''}" data-model="${v.id}"><a class="vehicle-visual ${v.id}" href="/models/${v.id}/">${img(v)}<span class="visual-index">${v.id.slice(-2)}</span></a><div class="vehicle-heading"><div><p class="eyebrow">${t(v.kind)}</p><h3><a href="/models/${v.id}/">${v.name}</a></h3></div>${a('/configure/?model='+v.id,t('configure'),'text-link')}</div><p class="vehicle-story">${t(v.id==='gt-01'?'gtStory':v.id==='cross-02'?'crossStory':'sportStory')}</p>${specs(v)}<div class="vehicle-bottom"><span>${t('from')} <strong>${curr(v.price)}</strong></span>${selection?`<label class="compare-toggle"><input type="checkbox" name="compare" value="${v.id}" ${compare.has(v.id)?'checked':''}> ${t('compare')}</label>`:''}</div></article>`;}
function notice(){return `<p class="disclosure">${t('numbersNote')}</p>`;}
function pageHeading(eye,title,sub=''){return `<section class="page-heading wrap"><p class="eyebrow">${esc(eye)}</p>${heading(title,'h1')}${sub?`<p class="lead">${esc(sub)}</p>`:''}</section>`;}
function home(){return `<section class="hero photographic-hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow">${t('eyebrow')}</p><h1 id="hero-title" class="balanced-heading"><span>${t('headline1')}</span><span>${t('headline2')}</span></h1><p>${t('heroSub')}</p><div class="button-row">${a('/collection/',t('discover'),'button primary')}${a('/configure/',t('configure'),'button glass')}</div><button type="button" class="hero-replay" data-action="replay"><span aria-hidden="true">▷</span> ${t('replay')}</button></div><figure class="hero-vehicle hero-photograph">${img(VEHICLES[2],'hero-car')}<figcaption>${t('photoLabel')} · Tesla Cybertruck</figcaption></figure><div class="hero-bottom"><span>TESLA CYBERTRUCK</span><a href="#collection">${t('scroll')} ↓</a><span>${t('photoLabel')}</span></div></section><section id="collection" class="section wrap"><div class="section-heading"><div><p class="eyebrow">MOTION COLLECTION</p>${heading(t('collectionTitle'))}</div>${a('/collection/',t('all'),'text-link')}</div><div class="vehicle-grid">${VEHICLES.map(v=>vehicleCard(v)).join('')}</div>${notice()}</section><section class="finder-feature"><div class="wrap feature-inner"><div><p class="eyebrow">${t('navFinder')}</p>${heading(t('homeFinderTitle'))}<p class="lead">${t('homeFinderBody')}</p>${a('/finder/',t('startFinder'),'button primary')}</div><div class="feature-car">${img(VEHICLES[1])}<span class="oversize-label" aria-hidden="true">02</span></div></div></section><section class="journey-feature wrap section"><div class="journey-photo" role="img" aria-label="${t('alpineScene')}"></div><div class="journey-copy"><p class="eyebrow">${t('navJourney')}</p>${heading(t('homeJourneyTitle'))}<p class="lead">${t('homeJourneyBody')}</p>${a('/journey/',t('planTrip'),'button dark')}</div></section><div class="wrap replay-row"><button class="text-button" data-action="replay">${t('replay')} ↺</button></div>`;}
function collection(){let list=VEHICLES.filter(v=>filter==='all'||v.kind===filter);if(sort==='price')list.sort((a,b)=>a.price-b.price);if(sort==='range')list.sort((a,b)=>b.battery/b.consumption-a.battery/a.consumption);const selected=VEHICLES.filter(v=>compare.has(v.id));return `${pageHeading(t('navCollection'),t('collectionTitle'),t('collectionSub'))}<section class="wrap section compact"><div class="collection-toolbar"><label>${t('filter')}<select id="vehicle-filter">${['all','grandTourer','crossover','pickup'].map(k=>`<option value="${k}" ${filter===k?'selected':''}>${t(k)}</option>`).join('')}</select></label><label>${t('sort')}<select id="vehicle-sort">${[['design','sortDesign'],['price','sortPrice'],['range','sortRange']].map(([v,k])=>`<option value="${v}" ${sort===v?'selected':''}>${t(k)}</option>`).join('')}</select></label></div><div class="vehicle-grid">${list.map(v=>vehicleCard(v,{selection:true})).join('')||`<p>${t('emptyFilter')}</p>`}</div>${notice()}<section id="comparison" class="comparison" tabindex="-1">${heading(t('comparison'))}${selected.length<2?`<p>${t('compareHint')}</p>`:`<div class="table-scroll" tabindex="0" role="region" aria-label="${t('comparison')}"><table><thead><tr><th scope="col">${t('model')}</th>${selected.map(v=>`<th scope="col">${v.name}</th>`).join('')}</tr></thead><tbody>${[['range',v=>num(Math.floor(v.battery/v.consumption*100))+' '+t('unitKm')],['battery',v=>v.battery+' '+t('unitKwh')],['consumption',v=>num(v.consumption,1)+' '+t('unitKwh')+t('per100')],['power',v=>v.power+' '+t('unitKw')],['seats',v=>v.seats],['from',v=>curr(v.price)]].map(([k,fn])=>`<tr><th scope="row">${t(k)}</th>${selected.map(v=>`<td>${fn(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}</section>${comparisonTray(selected)}</section>`;}
function comparisonTray(selected){return selected.length?`<aside class="compare-tray" role="region" aria-label="${t('comparison')}"><div><p role="status">${t('selectedCount')}: <strong>${selected.length}</strong></p><span>${selected.map(v=>esc(v.name)).join(' · ')}</span></div><button type="button" class="button primary" data-action="compare-jump" ${selected.length<2?'disabled':''}>${t('compare')} (${selected.length})</button><button type="button" class="compare-clear" data-action="clear-compare" aria-label="${t('clearCompare')}" title="${t('clearCompare')}">×</button></aside>`:'';}
function filmCover(v){return `<button type="button" class="film-cover" data-action="play-film" data-model="${v.id}" aria-label="${esc(t('filmPlay')+' · '+v.name)}">${img(v,'film-poster')}<span class="film-play-mark" aria-hidden="true"><svg viewBox="0 0 24 24" width="28" height="28"><path d="m9 5 11 7-11 7Z" fill="currentColor"/></svg></span><span class="film-play-label">${t('filmPlay')}</span></button>`;}
function modelFilm(v){const film=TESLA_FILMS[v.id];if(!film)return '';return `<section id="vehicle-film" class="model-film wrap section" aria-labelledby="film-heading"><div class="film-heading"><p class="eyebrow">${t('filmEyebrow')}</p>${heading(t('filmHeading'),'h2','id="film-heading"')}<p class="film-source-title">${esc(film.title)}</p></div><div class="film-stage" data-film-stage data-model="${v.id}">${filmCover(v)}</div><div class="film-controls"><a class="text-link" href="${esc(film.watchURL)}" target="_blank" rel="noopener noreferrer">${t('filmOnYouTube')} ${arrow}</a><button class="text-button" type="button" data-action="close-film" data-model="${v.id}" hidden>${t('filmClose')}</button></div><p class="film-status" role="status" data-film-status></p><p class="film-privacy">${t('filmPrivacy')}</p><p class="film-editions">${t('filmEditions')}</p></section>`;}
function playModelFilm(button){const section=button.closest('.model-film'),v=VEHICLES.find(x=>x.id===button.dataset.model),film=v&&TESLA_FILMS[v.id],stage=section?.querySelector('[data-film-stage]');if(!stage||!film)return;const frame=document.createElement('iframe');const url=new URL('https://www.youtube-nocookie.com/embed/'+film.youtubeId);url.search=new URLSearchParams({autoplay:'1',controls:'1',playsinline:'1',rel:'0',hl:state.lang,cc_lang_pref:state.lang,origin:location.origin}).toString();frame.setAttribute('title',film.title+' · Tesla · YouTube');frame.setAttribute('src',url.href);frame.setAttribute('allow','autoplay; encrypted-media; picture-in-picture; fullscreen');frame.setAttribute('allowfullscreen','');frame.setAttribute('referrerpolicy','strict-origin-when-cross-origin');frame.setAttribute('width','1280');frame.setAttribute('height','720');frame.addEventListener('error',()=>{section.querySelector('[data-film-status]').textContent=t('filmUnavailable');});stage.replaceChildren(frame);section.querySelector('[data-action="close-film"]').hidden=false;frame.focus();}
function closeModelFilm(button){const section=button.closest('.model-film'),v=VEHICLES.find(x=>x.id===button.dataset.model);if(!section||!v)return;section.querySelector('[data-film-stage]').innerHTML=filmCover(v);section.querySelector('[data-film-status]').textContent='';button.hidden=true;section.querySelector('[data-action="play-film"]').focus();}
function modelPage(id){const v=VEHICLES.find(v=>v.id===id);if(!v)return notFound();return `<section class="model-hero ${v.id}"><div class="wrap"><p class="eyebrow">${t(v.kind)} · ${t('concept')}</p><h1>${v.name}</h1><p class="model-tagline">${t(v.id==='gt-01'?'gtStory':v.id==='cross-02'?'crossStory':'sportStory')}</p>${img(v,'model-car')}<div class="button-row">${a('/configure/?model='+v.id,t('configure'),'button primary')}${a('/journey/?model='+v.id,t('planTrip'),'button outline')}<a class="text-link film-jump" href="#vehicle-film">${t('filmPlay')} <span aria-hidden="true">▷</span></a></div></div></section><section class="wrap section"><div class="model-spec-grid">${[['battery',v.battery+' '+t('unitKwh')],['power',v.power+' '+t('unitKw')],['range',num(Math.floor(v.battery/v.consumption*100))+' '+t('unitKm')],['consumption',num(v.consumption,1)+' '+t('unitKwh')+t('per100')],['seats',String(v.seats)],['acceleration',num(v.zero100,1)+' '+t('unitSeconds')]].map(([k,value])=>`<div><p>${t(k)}</p><strong>${value}</strong></div>`).join('')}</div>${notice()}</section>${modelFilm(v)}<section class="wrap section compact"><div class="editorial-band">${heading(t('homeFinderTitle'))}${a('/finder/',t('startFinder'),'button dark')}</div></section>`;}
// Older saved links remain readable without the removed paint surcharge.
function photoConfiguration(config){return {...config,paint:defaultConfig(config.model).paint};}
function configPage(){const v=vehicle(cfg.model),c=configuration(cfg);return `${pageHeading(t('navConfig'),t('configTitle'))}<div class="config-memory wrap"><p>${t(configRemembered?'choiceMemory':'choiceNotSaved')}</p><button type="button" class="text-button" data-action="reset-choice">${t('choiceReset')}</button></div><section class="config-layout wrap"><div class="config-stage"><div class="stage-top"><span>${v.name}</span><span>${t('concept')}</span></div>${img(v,'config-car')}<p class="stage-caption">${t('colorNote')}</p><div class="config-stats"><span><strong>${num(c.range)}</strong> ${t('unitKm')}<small>${t('range')}</small></span><span><strong>${num(c.consumption,1)}</strong> ${t('unitKwh')}${t('per100')}<small>${t('consumption')}</small></span></div></div><form class="config-controls" id="config-form"><label class="field">${t('model')}<select name="model">${VEHICLES.map(x=>`<option value="${x.id}" ${x.id===cfg.model?'selected':''}>${x.name}</option>`).join('')}</select></label>${optionGroup('wheels',WHEELS)}${optionGroup('interior',INTERIORS)}<p class="small muted">${t('wheelNote')}</p><div class="price-summary"><div><span>${t('base')}</span><span>${curr(v.price)}</span></div>${[WHEELS.find(x=>x.id===cfg.wheels),INTERIORS.find(x=>x.id===cfg.interior)].filter(x=>x.price).map(x=>`<div><span>${t(x.id)}</span><span>+ ${curr(x.price)}</span></div>`).join('')}<div class="total"><span>${t('total')}</span><strong>${curr(c.price)}</strong></div></div><button type="button" class="button primary full" data-action="save">${t('save')} ${arrow}</button><div class="config-actions"><button type="button" class="text-button" data-action="share">${t('share')} ↗</button><button type="button" class="text-button" data-action="download">${t('download')} ↓</button></div><p class="small muted">${t('garageLocal')}</p></form></section><div class="wrap">${notice()}</div>`;}
function optionGroup(key,values){return `<fieldset><legend>${t(key)}</legend><div class="option-list">${values.map(o=>`<label class="option-row"><input type="radio" name="${key}" value="${o.id}" ${cfg[key]===o.id?'checked':''}><span>${t(o.id)}</span><span>${o.price?'+ '+curr(o.price):t('included')}</span></label>`).join('')}</div></fieldset>`;}
function finder(){const list=quizResult||[];return `${pageHeading(t('navFinder'),t('finderTitle'),t('homeFinderBody'))}<section class="finder-layout wrap section compact"><form id="finder-form" class="panel"><label class="field">${t('budget')} · EUR<input type="number" name="budget" min="10000" max="200000" step="500" required value="${quiz.budget}"></label><label class="field">${t('requiredSeats')}<select name="seats">${[2,3,4,5].map(n=>`<option value="${n}" ${n===quiz.seats?'selected':''}>${n}</option>`).join('')}</select></label><fieldset><legend>${t('priority')}</legend>${['distance','family','performance'].map(k=>`<label class="option-row"><input type="radio" name="priority" value="${k}" ${quiz.priority===k?'checked':''}><span>${t(k)}</span></label>`).join('')}</fieldset><button class="button primary full" type="submit">${t('find')} ${arrow}</button><p class="small muted">${t('rulesNote')}</p></form><div id="finder-result" aria-live="polite">${list.length?`<p class="eyebrow">${t('recommendation')}</p>${list[0].eligible?'':`<p class="alert">${t('noMatch')}</p>`}${vehicleCard(list[0].v)}<div class="why"><h3>${t('why')}</h3><ul>${[[list[0].v.price<=quiz.budget*100,'fitsBudget'],[list[0].v.seats>=quiz.seats,'fitsSeats'],[list[0].v.tag===quiz.priority,'fitsPriority']].filter(([yes])=>yes).map(([,k])=>`<li>${t(k)}</li>`).join('')}</ul></div>`:`<div class="finder-placeholder">${img(VEHICLES[0])}<p>${t('homeFinderTitle')}</p></div>`}</div></section>`;}
function cityOptions(value){return CITIES.map(c=>`<option value="${c.id}" ${c.id===value?'selected':''}>${t(c.id)}</option>`).join('');}
function journey(){const v=vehicle(trip.model);return `${pageHeading(t('navJourney'),t('journeyTitle'))}<section class="journey-layout wrap section compact"><form id="trip-form" class="panel"><div class="field-pair"><label class="field">${t('origin')}<select name="from">${cityOptions(trip.from)}</select></label><label class="field">${t('destination')}<select name="to">${cityOptions(trip.to)}</select></label></div><label class="field">${t('model')}<select name="model">${VEHICLES.map(x=>`<option value="${x.id}" ${x.id===v.id?'selected':''}>${x.name}</option>`).join('')}</select></label><div class="field-pair"><label class="field">${t('startSoc')} · %<input type="number" name="start" min="20" max="100" required value="${trip.start}"></label><label class="field">${t('reserve')} · %<input type="number" name="reserve" min="5" max="40" required value="${trip.reserve}"></label></div><label class="field">${t('electricity')} · EUR/${t('unitKwh')}<input type="number" name="price" min="0" max="3" step=".01" required value="${trip.price}"></label><button type="submit" class="button primary full" ${tripBusy?'disabled':''}>${t(tripBusy?'loading':'calculate')} ${arrow}</button><p class="small muted">${t('externalNote')}</p></form><div id="trip-output" aria-live="polite">${tripFailed?`<div class="alert"><p>${t('routeFailure')}</p><button class="button outline" data-action="estimate">${t('estimate')}</button></div>`:''}${tripResult?renderTrip():`<div class="trip-placeholder"><span class="route-illustration" aria-hidden="true">↗</span>${heading(t('homeJourneyTitle'))}<p>${t('homeJourneyBody')}</p>${img(v)}</div>`}</div></section>`;}
function renderTrip(){const r=tripResult,from=CITIES.find(x=>x.id===trip.from),to=CITIES.find(x=>x.id===trip.to),d=routePath(r.geometry);return `<div class="route-result"><p class="eyebrow ${r.estimated?'estimated':''}">${t(r.estimated?'estimatedRoute':'liveRoute')}</p><h2>${t(trip.from)} <span class="muted">→</span> ${t(trip.to)}</h2><section class="route-map-section"><div class="map-viewport"><div id="route-map" class="route-map" role="region" aria-label="${t('interactiveMap')}" hidden></div><div class="route-canvas" data-map-fallback><svg viewBox="0 0 900 440" role="img" aria-label="${t('routeDiagram')}"><defs><pattern id="grid" width="50" height="50" patternUnits="userSpaceOnUse"><path d="M 50 0 L 0 0 0 50" fill="none" stroke="#d7e6ed" stroke-width="1"/></pattern></defs><rect width="900" height="440" fill="url(#grid)"/><path class="route-shadow" d="${d}"/><path class="route-line ${r.estimated?'dashed':''}" d="${d}"/></svg><span class="map-north" aria-hidden="true">N ↑</span><p>${t('routeDiagram')} · © OpenStreetMap contributors</p></div></div><p id="map-status" class="map-status" role="status">${t('mapLoading')}</p><div class="map-controls"><button class="text-button" data-action="fit-map" disabled>${t('mapFit')}</button><button class="text-button" data-action="retry-map" hidden>${t('mapRetry')}</button></div><p class="map-privacy">${t('mapPrivacy')}</p></section><div class="trip-metrics">${[['distanceLabel',num(r.distance)+' '+t('unitKm')],['duration',num(Math.floor(Math.round(r.duration)/60))+' '+t('unitHours')+' '+num(Math.round(r.duration)%60)+' '+t('unitMinutes')],['energy',num(r.energy.required,1)+' '+t('unitKwh')],['stops',String(r.energy.stops)],['charging',num(r.energy.chargingMinutes)+' '+t('unitMinutes')],['energyCost',new Intl.NumberFormat(LOCALES[state.lang],{style:'currency',currency:'EUR'}).format(r.energy.cost)]].map(([k,v])=>`<div><span>${t(k)}</span><strong>${v}</strong></div>`).join('')}</div><p class="small muted">${t('chargingEnergy')}: ${num(r.energy.extra,1)} ${t('unitKwh')}</p><p class="disclosure">${t('tripNote')}</p><a class="text-link" href="https://www.openstreetmap.org/directions?engine=fossgis_osrm_car&route=${from.lat}%2C${from.lon}%3B${to.lat}%2C${to.lon}" target="_blank" rel="noopener noreferrer">${t('openMap')} ↗</a><section class="weather-box"><button class="button outline" data-action="weather" ${weatherBusy?'disabled':''}>${t(weatherBusy?'loading':'weather')}</button>${weatherFailed?`<p role="alert">${t('weatherFailure')}</p>`:''}${weatherResult?`<h3>${t('weatherTitle')}</h3><div class="weather-values"><span>${t('temperature')} <strong>${num(weatherResult.temperature,1)} °C</strong></span><span>${t('wind')} <strong>${num(weatherResult.wind,1)} ${t('unitSpeed')}</strong></span></div><p class="small muted">${t('asOf')}: ${esc(weatherResult.time.replace('T',' '))} · <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a> · CC BY 4.0</p>`:''}</section></div>`;}
function garage(){return `${pageHeading(t('navGarage'),t('garageTitle'),t('garageLocal'))}<section class="wrap section compact">${state.garage.length?`<div class="garage-grid">${state.garage.map(item=>{const c=configuration(photoConfiguration(item.config)),v=vehicle(c.model);return `<article class="garage-item"><div class="vehicle-visual">${img(v)}</div><div class="garage-body"><h2>${v.name}</h2><p>${t(c.wheels)} · ${t(c.interior)}</p><strong class="garage-price">${curr(c.price)}</strong><p class="small muted">${t('savedAt')} ${new Intl.DateTimeFormat(LOCALES[state.lang],{dateStyle:'medium'}).format(new Date(item.savedAt))}</p><div class="button-row">${a('/configure/?'+encodeConfig(c),t('edit'),'button outline')}<button class="text-button" data-action="remove" data-id="${esc(item.id)}">${t('remove')}</button></div></div></article>`;}).join('')}</div>`:`<div class="empty-garage">${img(VEHICLES[0])}${heading(t('garageEmpty'))}${a('/configure/',t('configure'),'button primary')}</div>`}</section>`;}
function about(){return `${pageHeading(t('navAbout'),t('aboutTitle'),t('aboutBody'))}<section class="about-layout wrap section compact"><div class="about-visual">${img(VEHICLES[0])}<span>MOTION / 2026</span></div><div class="about-text">${[['working','workingBody'],['limits','limitsBody'],['human','humanBody']].map(([h,b])=>`<section><h2>${t(h)}</h2><p>${t(b)}</p></section>`).join('')}<section>${heading(t('photoCredits'))}<div class="photo-credit-list">${PHOTO_CREDITS.map(c=>`<div><strong>${esc(c.realmodel)}</strong><p><a href="${esc(c.originalsourceURL)}" target="_blank" rel="noopener noreferrer">${esc(c.author)}</a> · <a href="${esc(c.licenseURL)}" target="_blank" rel="noopener noreferrer">${esc(c.license)}</a></p><p class="small">${t('photoChange')}</p></div>`).join('')}</div><p class="small"><a href="/assets/fonts/OFL.txt" target="_blank" rel="noopener noreferrer">${t('fontCredit')}</a></p></section><section>${heading(t('videoCredits'))}<p><a href="${esc(INTRO_CLIP.sourceURL)}" target="_blank" rel="noopener noreferrer">${esc(INTRO_CLIP.title)}</a> · ${esc(INTRO_CLIP.author)} · <a href="${esc(INTRO_CLIP.licenseURL)}" target="_blank" rel="noopener noreferrer">${esc(INTRO_CLIP.license)}</a></p><p class="small">${t('videoChange')}</p></section><section>${heading(t('filmCredits'))}<p>${t('filmCreditsBody')}</p><ul>${Object.entries(TESLA_FILMS).map(([id,film])=>`<li><a href="${esc(film.watchURL)}" target="_blank" rel="noopener noreferrer">${esc(vehicle(id).name)} · ${esc(film.title)}</a></li>`).join('')}</ul></section><section id="music-credits">${heading(t('musicCredits'))}<p><a href="${esc(INTRO_MUSIC.sourceURL)}" target="_blank" rel="noopener noreferrer">${esc(INTRO_MUSIC.title)}</a> · ${esc(INTRO_MUSIC.author)} · <a href="${esc(INTRO_MUSIC.licenseURL)}" target="_blank" rel="noopener noreferrer">${esc(INTRO_MUSIC.license)}</a></p><p class="small">${t('musicChange')}</p></section><section>${heading(t('sources'))}<ul><li><a href="https://project-osrm.org/" target="_blank" rel="noopener noreferrer">OSRM</a> · <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">© OpenStreetMap contributors · ODbL</a></li><li><a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo · CC BY 4.0</a></li><li><a href="https://leafletjs.com/" target="_blank" rel="noopener noreferrer">Leaflet 1.9.4</a> · <a href="/assets/vendor/leaflet/LICENSE" target="_blank" rel="noopener noreferrer">BSD-2-Clause</a></li><li>${a('https://github.com/Netaniya/Netaniya/tree/main/portfolio/motion-atelier',t('viewCode'))}</li></ul></section></div></section>`;}
function notFound(){return `${pageHeading('404',t('notFound'))}<div class="wrap section">${a('/',t('backHome'),'button primary')}</div>`;}
function content(){if(isHome)return home();if(path==='/collection/')return collection();if(path==='/configure/')return configPage();if(path==='/finder/')return finder();if(path==='/journey/')return journey();if(path==='/garage/')return garage();if(path==='/about/')return about();if(path.startsWith('/models/'))return modelPage(path.split('/')[2]);return notFound();}
function render(focusName){routeMap.destroy();t=translator(state.lang);document.documentElement.lang=state.lang;document.documentElement.dataset.theme=state.theme;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',state.theme==='dark'?'#101820':'#fbfcfc');root.innerHTML=header()+`<main id="main">${state.error?`<div class="storage-banner" role="status">${t('storageError')}</div>`:''}${content()}</main>`+footer();const titles={'/collection/':'navCollection','/configure/':'navConfig','/finder/':'navFinder','/journey/':'navJourney','/garage/':'navGarage','/about/':'navAbout'};document.title=(titles[path]?t(titles[path]):path.startsWith('/models/')?vehicle(path.split('/')[2]).name:'Motion Atelier')+' — Motion Atelier';document.body.classList.toggle('has-compare',path==='/collection/'&&compare.size>0);experience.syncMenu(menuOpen);experience.decorate();updateClock();if(path==='/journey/'&&tripResult)mountTripMap();if(focusName){const node=root.querySelector(focusName);if(node){if(!node.matches('a,button,input,select,textarea'))node.tabIndex=-1;node.focus();}}}
function mountTripMap(){if(!tripResult)return;routeMap.mount({container:document.getElementById('route-map'),fallback:document.querySelector('[data-map-fallback]'),status:document.getElementById('map-status'),retry:document.querySelector('[data-action="retry-map"]'),fitButton:document.querySelector('[data-action="fit-map"]'),geometry:tripResult.geometry,fromName:t(trip.from),toName:t(trip.to),estimated:tripResult.estimated,labels:{loading:t('mapLoading'),ready:t('mapReady'),estimated:t('mapEstimate'),unavailable:t('mapUnavailable'),zoomIn:t('zoomIn'),zoomOut:t('zoomOut')}});}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function exportJson(data,filename){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),el=document.createElement('a');el.href=url;el.download=filename;el.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function freshGarage(){if(state.error)return state.garage;try{return validateGarage(storage.getItem('motion-garage'));}catch{state.error=true;return state.garage;}}
function persistGarage(items){state.garage=items;try{if(state.error)throw Error('blocked');storage.setItem('motion-garage',JSON.stringify(items));return true;}catch{state.error=true;return false;}}
function resetTrip(){controller?.abort();weatherController?.abort();controller=null;weatherController=null;tripResult=null;tripFailed=false;tripBusy=false;weatherResult=null;weatherFailed=false;weatherBusy=false;}
root.addEventListener('change',e=>{const el=e.target;if(el.id==='language'){state.lang=el.value;t=translator(state.lang);try{storage.setItem('motion-language',state.lang);}catch{state.error=true;}menuOpen=false;render('#language');return;}if(el.id==='vehicle-filter'){filter=el.value;render('#vehicle-filter');}if(el.id==='vehicle-sort'){sort=el.value;render('#vehicle-sort');}if(el.name==='compare'){if(el.checked)compare.add(el.value);else compare.delete(el.value);rememberComparison(storage,compare);render(`input[name="compare"][value="${el.value}"]`);}if(el.closest('#config-form')){cfg={...cfg,[el.name]:el.value};configRemembered=rememberConfig(storage,cfg);history.replaceState(null,'','?'+encodeConfig(cfg));render(el.name==='model'?'#config-form [name="model"]':`[name="${el.name}"][value="${el.value}"]`);}if(el.closest('#trip-form')){trip={...trip,[el.name]:['start','reserve','price'].includes(el.name)?Number(el.value):el.value};resetTrip();render(`#trip-form [name="${el.name}"]`);}if(el.closest('#finder-form')){quiz={...quiz,[el.name]:['budget','seats'].includes(el.name)?Number(el.value):el.value};quizResult=null;document.getElementById('finder-result').innerHTML='';}});
root.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='finder-form'){const d=new FormData(e.target);quiz={budget:Number(d.get('budget')),seats:Number(d.get('seats')),priority:d.get('priority')};try{quizResult=recommend(quiz);render('#finder-result h3 a');}catch{toast(t('invalid'));}}if(e.target.id==='trip-form'){const d=new FormData(e.target);trip={from:d.get('from'),to:d.get('to'),model:d.get('model'),start:Number(d.get('start')),reserve:Number(d.get('reserve')),price:Number(d.get('price'))};await calculateTrip(false);}});
async function calculateTrip(estimate){resetTrip();if(trip.from===trip.to){toast(t('sameCity'));return;}const v=vehicle(trip.model),from=CITIES.find(x=>x.id===trip.from),to=CITIES.find(x=>x.id===trip.to);try{planEnergy({distance:0,battery:v.battery,consumption:v.consumption,start:trip.start,reserve:trip.reserve,price:trip.price,chargeKw:v.chargeKw});}catch{toast(t('invalid'));return;}tripBusy=true;render();const own=new AbortController();controller=own;const timer=setTimeout(()=>own.abort(),12000);try{const result=estimate?{distance:haversine(from,to)*1.25,duration:haversine(from,to)*1.25/80*60,geometry:[[from.lon,from.lat],[to.lon,to.lat]],estimated:true}:await fetchRoute(from,to,{signal:own.signal});if(controller!==own)return;tripResult={...result,energy:planEnergy({distance:result.distance,battery:v.battery,consumption:v.consumption,start:trip.start,reserve:trip.reserve,price:trip.price,chargeKw:v.chargeKw})};tripFailed=false;}catch{if(controller===own)tripFailed=true;}finally{clearTimeout(timer);if(controller===own){tripBusy=false;render();}}}
root.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action;if(act==='theme'){state.theme=state.theme==='dark'?'light':'dark';try{storage.setItem('motion-theme',state.theme);}catch{}render('.theme-toggle');}if(act==='menu'){menuOpen=!menuOpen;experience.syncMenu(menuOpen);b.setAttribute('aria-label',t(menuOpen?'close':'menu'));}if(act==='play-film')playModelFilm(b);if(act==='close-film')closeModelFilm(b);if(act==='replay')startIntro(true);if(act==='fit-map')routeMap.fit();if(act==='retry-map')mountTripMap();
if(act==='clear-compare'){compare.clear();rememberComparison(storage,compare);render('#comparison');}
if(act==='compare-jump'&&compare.size>=2){const target=document.getElementById('comparison');target.scrollIntoView?.({behavior:experience.reduced()?'auto':'smooth',block:'start'});target.focus({preventScroll:true});}
if(act==='reset-choice'){cfg=defaultConfig();configRemembered=rememberConfig(storage,cfg);history.replaceState(null,'','?'+encodeConfig(cfg));render('#config-form select');toast(t('choiceResetDone'));}
if(act==='save'){const list=freshGarage();if(list.length>=30){toast(t('garageFull'));return;}const duplicate=list.some(x=>encodeConfig(photoConfiguration(x.config))===encodeConfig(cfg));configRemembered=rememberConfig(storage,cfg);if(!duplicate)persistGarage([...list,{id:crypto.randomUUID(),savedAt:new Date().toISOString(),config:{...cfg}}]);render();toast(t(state.error?'storageError':duplicate?'alreadySaved':'saved'));const savedButton=root.querySelector('[data-action="save"]');savedButton?.classList.add('action-confirmed');}if(act==='share'){const url=new URL('/configure/?'+encodeConfig(cfg),location.origin).href;try{await navigator.clipboard.writeText(url);toast(t('copied'));}catch{const box=document.getElementById('share-fallback');box.replaceChildren();const label=document.createElement('label');label.textContent=t('copyManual');const input=document.createElement('input');input.readOnly=true;input.value=url;label.append(input);box.append(label);box.hidden=false;input.focus();input.select();}}if(act==='download'){exportJson({schema:'motion-atelier.configuration.v1',language:state.lang,fictional:true,config:cfg,calculation:configuration(cfg),exportedAt:new Date().toISOString()},'motion-atelier-'+cfg.model+'.json');}if(act==='remove'){if(!confirm(t('confirmRemove')))return;const list=freshGarage();persistGarage(list.filter(x=>x.id!==b.dataset.id));render();}if(act==='estimate')await calculateTrip(true);if(act==='weather'&&tripResult){weatherController?.abort();const own=new AbortController();weatherController=own;weatherBusy=true;weatherFailed=false;render();const timer=setTimeout(()=>own.abort(),10000);try{const w=await fetchWeather(CITIES.find(x=>x.id===trip.to),{signal:own.signal});if(weatherController===own)weatherResult=w;}catch{if(weatherController===own)weatherFailed=true;}finally{clearTimeout(timer);if(weatherController===own){weatherBusy=false;render();}}}});
window.addEventListener('storage',e=>{if(['motion-garage','motion-theme',null].includes(e.key)){const latest=loadState(storage);state.garage=latest.garage;state.error=latest.error;state.theme=latest.theme;render();}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){const overlay=document.getElementById('arrival');if(!overlay.hidden)finishIntro();else if(menuOpen){menuOpen=false;experience.syncMenu(false);const button=root.querySelector('.menu-toggle');button?.setAttribute('aria-label',t('menu'));button?.focus();}}});
const intro=document.getElementById('arrival'),introVideo=intro.querySelector('video'),introPlay=intro.querySelector('[data-intro-play]'),introSound=intro.querySelector('[data-intro-sound]'),introAudio=document.getElementById('intro-music');
let introTimer,introHideTimer,introLoadTimer,introRun=0,musicRun=0,musicEnabled=false,musicFades=[],musicAttempted=false,musicBlocked=false,musicSuppressed=false;
function updateSoundControl(){introSound.textContent=t(musicEnabled?'soundOff':'soundEnable');intro.querySelector('[data-sound-hint]').hidden=!musicBlocked;intro.querySelector('[data-sound-hint]').textContent=t('soundBlocked');introSound.setAttribute('aria-pressed',String(musicEnabled));intro.querySelector('[data-music-credit]').hidden=!musicEnabled;}
function stopMusic(immediate=false){
 const wasEnabled=musicEnabled;const run=++musicRun;for(const timer of musicFades)clearTimeout(timer);musicFades=[];musicEnabled=false;musicBlocked=false;updateSoundControl();
 const stop=()=>{if(run!==musicRun)return;introAudio.pause();introAudio.currentTime=0;introAudio.volume=.6;};
 if(immediate||!wasEnabled){stop();return;}
 const start=introAudio.volume;for(let i=1;i<=8;i++)musicFades.push(setTimeout(()=>{if(run!==musicRun)return;introAudio.volume=Math.max(0,start*(1-i/8));if(i===8)stop();},i*35));
}
function startMusic(automatic=false){
 stopMusic(true);const run=++musicRun;musicEnabled=true;updateSoundControl();introAudio.src=INTRO_MUSIC.src;introAudio.volume=.6;introAudio.currentTime=automatic?Math.max(0,Math.min(5,introVideo.currentTime||0)):0;
 const failed=error=>{if(run!==musicRun)return;stopMusic(true);if(automatic&&error?.name==='NotAllowedError'){musicBlocked=true;updateSoundControl();}else toast(t('audioUnavailable'));};
 try{const playback=introAudio.play();if(playback?.catch)playback.catch(failed);}catch{failed();}
}

function finishIntro(){
 if(intro.hidden)return;
 ++introRun;stopMusic();clearTimeout(introTimer);clearTimeout(introHideTimer);clearTimeout(introLoadTimer);
 introVideo.pause();intro.classList.add('departed');intro.classList.remove('needs-play','loading');
 document.body.classList.remove('intro-playing');root.inert=false;intro.inert=true;experience.decorate();
 if(intro.contains(document.activeElement)){const main=document.getElementById('main');main.tabIndex=-1;main.focus({preventScroll:true});}
 introHideTimer=setTimeout(()=>{intro.hidden=true;introVideo.removeAttribute('src');introVideo.load();},850);
}
function requestIntroPlayback(run){
 if(run!==introRun||intro.hidden||intro.inert)return;
 intro.classList.remove('needs-play');introPlay.hidden=true;intro.classList.add('loading');clearTimeout(introLoadTimer);introLoadTimer=setTimeout(finishIntro,10000);
 const blocked=()=>{if(run!==introRun||intro.inert)return;intro.classList.remove('loading');intro.classList.add('needs-play');introPlay.hidden=false;};
 try{const playback=introVideo.play();if(playback?.catch)playback.catch(blocked);}catch{blocked();}
}
function startIntro(force=false){
 if(!isHome)return;
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){intro.hidden=true;return;}
 clearTimeout(introTimer);clearTimeout(introHideTimer);clearTimeout(introLoadTimer);const run=++introRun;
 stopMusic(true);musicAttempted=false;introVideo.pause();introVideo.muted=true;introVideo.defaultMuted=true;introVideo.playsInline=true;
 intro.hidden=false;intro.inert=false;intro.classList.remove('departed','playing','needs-play');
 intro.querySelector('[data-intro-label]').textContent=t('introText');intro.querySelector('[data-intro-skip]').textContent=t('skipIntro');
 intro.querySelector('[data-intro-author]').innerHTML=authorStrip('intro-meta');updateClock();introVideo.setAttribute('aria-label',t('filmLabel'));introPlay.textContent=t('playIntro');introPlay.hidden=true;
 intro.querySelector('[data-intro-credit]').textContent=INTRO_CLIP.author+' · '+INTRO_CLIP.license;
 intro.querySelector('[data-intro-credit]').href=INTRO_CLIP.sourceURL;intro.querySelector('[data-music-credit]').textContent=INTRO_MUSIC.title+' · Kevin MacLeod · '+INTRO_MUSIC.license;intro.querySelector('[data-music-credit]').href='/about/#music-credits';
 if(force){const previous=document.documentElement.style.scrollBehavior;document.documentElement.style.scrollBehavior='auto';window.scrollTo(0,0);document.documentElement.style.scrollBehavior=previous;}
 document.body.classList.add('intro-playing');root.inert=true;intro.querySelector('[data-intro-skip]').focus({preventScroll:true});
 introVideo.src=INTRO_CLIP.src;introVideo.currentTime=0;introVideo.load();
 introLoadTimer=setTimeout(finishIntro,10000);requestIntroPlayback(run);
}
function armIntroDeadline(){clearTimeout(introTimer);const remaining=Number.isFinite(introVideo.duration)&&introVideo.duration>0?Math.max(0,introVideo.duration-introVideo.currentTime):7.5;const length=Math.min(remaining*1000+500,12000);intro.style.setProperty('--film-duration',Math.max(0,length-500)+'ms');introTimer=setTimeout(finishIntro,length);}
introVideo.addEventListener('playing',()=>{
 if(intro.hidden||intro.inert)return;
 clearTimeout(introLoadTimer);intro.classList.remove('loading','needs-play');introPlay.hidden=true;intro.classList.add('playing');armIntroDeadline();if(!musicAttempted&&!musicSuppressed){musicAttempted=true;startMusic(true);}
});
introVideo.addEventListener('ended',finishIntro);
introVideo.addEventListener('error',()=>{if(!intro.hidden&&!intro.inert){finishIntro();toast(t('introUnavailable'));}});
introPlay.addEventListener('click',()=>requestIntroPlayback(introRun));
introSound.addEventListener('click',()=>{if(musicEnabled){musicSuppressed=true;stopMusic();return;}musicSuppressed=false;musicAttempted=true;introVideo.currentTime=0;if(intro.classList.contains('playing'))armIntroDeadline();requestIntroPlayback(introRun);startMusic();});
introAudio.addEventListener('error',()=>{if(musicEnabled){stopMusic(true);toast(t('audioUnavailable'));}});
introAudio.addEventListener('ended',()=>stopMusic(true));
window.addEventListener('pagehide',()=>stopMusic(true));
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopMusic(true);});
intro.querySelector('[data-intro-skip]').addEventListener('click',finishIntro);
const selectedModel=new URLSearchParams(location.search).get('model');if(path==='/journey/'&&VEHICLES.some(v=>v.id===selectedModel))trip.model=selectedModel;
if(path==='/configure/')configRemembered=rememberConfig(storage,cfg);
render();if(isHome)startIntro();else intro.hidden=true;
